<script setup lang="ts">
import{describeLiveFailure}from'~/features/live-core/gateway';import type{VolunteerOverview}from'~/features/entry-live/gateway';
useSeoMeta({title:'志愿服务｜语赞心声'});const gateway=useEntryLiveGateway();const state=ref<'loading'|'ready'|'empty'|'error'>('loading');const overview=ref<VolunteerOverview|null>(null);const failure=ref<ReturnType<typeof describeLiveFailure>|null>(null);async function load(){state.value='loading';try{overview.value=await gateway.volunteerOverview();state.value=overview.value.volunteers.length||overview.value.training.length||overview.value.pairings.length?'ready':'empty'}catch(error){failure.value=describeLiveFailure(error);state.value='error'}}await load();
</script>
<template><section class="volunteer" aria-labelledby="volunteer-title"><header class="volunteer__hero"><div class="yx-shell"><p class="yx-kicker">SERVICE DESK · SCHOOL SCOPED</p><h1 id="volunteer-title">把热心放进<br>可监督的服务链。</h1><p v-if="overview">{{overview.context.schoolName}} · {{overview.context.role}}</p></div></header><div class="yx-shell volunteer__body"><section v-if="state==='loading'" class="state" aria-live="polite"><h2>正在读取志愿者、培训与配对……</h2></section><section v-else-if="state==='error'" class="state" role="alert"><p class="yx-kicker">{{failure?.code||failure?.kind}}</p><h2>{{failure?.message}}</h2><p>接口按当前会员角色执行；没有权限时不会回退到演示名单。</p><NuxtLink v-if="failure?.kind==='unauthenticated'" to="/login?redirect=/volunteer">重新登录</NuxtLink><NuxtLink v-else-if="failure?.kind==='permission'" to="/select-school">切换学校</NuxtLink><button v-else type="button" @click="load">重试</button></section><template v-else-if="overview"><section class="pulse"><div><strong>{{overview.volunteers.length}}</strong><span>真实志愿档案</span></div><div><strong>{{overview.training.length}}</strong><span>培训项目</span></div><div><strong>{{overview.pairings.length}}</strong><span>支持配对</span></div></section><section v-if="state==='empty'" class="empty"><p class="yx-kicker">REAL EMPTY</p><h2>当前学校还没有志愿服务记录。</h2><p>页面没有使用 VM 头像、课程或任务演示数据。</p></section><section v-else class="service"><div><p class="yx-kicker">01 · PEOPLE</p><h2>志愿档案</h2><ol><li v-for="item in overview.volunteers" :key="item.id"><strong>{{item.displayName}}</strong><span>{{item.status}}</span><small>{{item.appliedAt}}</small></li></ol><p v-if="!overview.volunteers.length">没有可见档案。</p></div><div><p class="yx-kicker">02 · READINESS</p><h2>培训项目</h2><ol><li v-for="item in overview.training" :key="item.id"><strong>{{item.title}}</strong><span>{{item.status}}</span><small>{{item.modules.length}} 个模块</small></li></ol><p v-if="!overview.training.length">没有已配置培训。</p></div><div><p class="yx-kicker">03 · SUPERVISION</p><h2>支持配对</h2><ol><li v-for="item in overview.pairings" :key="item.id"><strong>{{item.goal}}</strong><span>{{item.status}}</span><small>{{item.consentStatus||'最小披露视图'}}</small></li></ol><p v-if="!overview.pairings.length">没有可见配对。</p></div></section></template><footer><p>服务任务、会话和风险信息仍由教师监督与后端权限过滤；本页不展示家庭或心理敏感详情。</p></footer></div></section></template>
